function db():PDO{return $GLOBALS['db'];}function fail(string $m,int $code=422):never{throw new RuntimeException($m,$code);}
function query(string $sql,array $params=[]):PDOStatement{if(str_contains($sql,'information_schema.tables'))$sql="SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='yard_expenses'";$sql=str_replace([' FOR UPDATE','INSERT IGNORE'],['','INSERT OR IGNORE'],$sql);$s=db()->prepare($sql);$s->execute($params);return $s;}
function transaction(callable $fn):void{db()->beginTransaction();try{$fn();db()->commit();}catch(Throwable $e){db()->rollBack();throw $e;}}
function assertWorkspaceDate(string $date):string{if($date<'2026-04-01'||$date>'2027-03-31')fail('Wrong year');return $date;}
function postingDate(array $d,string $k):string{$v=(string)($d[$k]??'');$p=DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$p||$p->format('Y-m-d')!==$v)fail('Invalid date');return assertWorkspaceDate($v);}
function master(array $d,string $k,string $kind,bool $required=true):?int{$id=(int)($d[$k]??0);if(!$id&&!$required)return null;if(!query('SELECT id FROM masters WHERE id=? AND kind=?',[$id,$kind])->fetchColumn())fail('Invalid master');return $id;}
function money(array $d,string $k):string{$v=(string)($d[$k]??'');if(!preg_match('/^\d{1,10}(\.\d{1,2})?$/',$v))fail('Invalid amount');return $v;}
function txt(array $d,string $k,int $max,bool $required=true):string{$v=strtoupper(trim((string)($d[$k]??'')));if(($required&&$v==='')||strlen($v)>$max)fail('Invalid text');return $v;}
function audit(string $a,int $id):void{query('INSERT INTO audit_log VALUES(?,?)',[$a,$id]);}
function check(bool $ok,string $m):void{if(!$ok)throw new LogicException($m);}
function rejects(callable $fn):void{try{$fn();}catch(RuntimeException $e){return;}throw new LogicException('Expected rejection');}
